def encrypt(s):
    alphabet = 'abcdefghijklmnopqrstuvwxyz'
    result = []
    for char in s.lower():
        if char in alphabet:
            shifted = (alphabet.index(char) + (2 ** 2)) % 26
            result.append(alphabet[shifted])
        else:
            result.append(char)
    return ''.join(result)
